    const html = `<!doctype html><meta charset="utf-8"><title>${data.label}</title>` +
                 `<body style="font:16px system-ui;padding:2rem"><h1>${data.label}</h1>` +
                 `<p>Long-running Sprite service for musical theater.</p></body>`;
